+// mimalloc: _mi_segment_page_of
+MALLOC_ALWAYS_INLINE MALLOC_INLINE
+static xzm_chunk_t
+_xzm_segment_chunk_of(xzm_segment_t segment, uintptr_t ptr)
+{
+	xzm_slice_t slice = _xzm_segment_slice_of(segment, ptr);
+	if (!slice) {
+		return NULL;
