+MALLOC_ALWAYS_INLINE MALLOC_INLINE
+static bool
+_xzm_slice_meta_is_batch_pointer(xzm_malloc_zone_t zone, xzm_slice_t slice)
+{
+#if CONFIG_XZM_DEFERRED_RECLAIM
+	if ((mach_vm_reclaim_id_t)slice == VM_RECLAIM_ID_NULL) {
