+	case XZM_SEGMENT_GROUP_POINTER_XZONES:
+	case XZM_SEGMENT_GROUP_DATA:
+		return small_block_size_min;
+	case XZM_SEGMENT_GROUP_POINTER_LARGE:
+	case XZM_SEGMENT_GROUP_DATA_LARGE:
+		return large_block_size_min;
