+
+		printer("\"chunk_threshold\": %u, \n", main->xzmz_xzone_chunk_threshold);
+		printer("\"ptr_bucket_count\": %d, \n", main->xzmz_ptr_bucket_count);
+
+#if CONFIG_MTE
+		printer("\"mte_config\": {\n");
+		printer("    \"enabled\": %d, \n",
+				(int)main->xzmz_base.xzz_memtag_config.enabled);
