+	if (data_large) {
+		T_ASSERT_EQ((int)sgid, XZM_SEGMENT_GROUP_DATA_LARGE, "data segment group");
+	} else {
+		T_ASSERT_EQ((int)sgid, XZM_SEGMENT_GROUP_DATA, "data segment group");
