+T_DECL(mte_unit_memtag_init_chunk,
+	"Check that memtag_init_chunk works")
+{
+	T_SKIP_REQUIRES_SEC_TRANSITION();
+
+	uint8_t *page_addr = NULL;
+	allocate_mte_pages(1, (vm_address_t *)&page_addr);
