+	for (size_t sz = 16; sz < PAGE_SIZE / 4; sz += 16) {
+		const size_t remainder = PAGE_SIZE % sz;
+		// Reset the tags on the page
+		for (size_t i = 0; i < PAGE_SIZE; i += 16) {
+			__arm_mte_set_tag(&page_addr[i]);
